SELECT ?s ?name ?tsid ?pointclass WHERE {
  ?s rdf:type brick:Chiller .
  ?s rdfs:label ?name .
  ?s ref:hasExternalReference [ ref:hasTimeseriesId ?tsid ] .
}

SELECT ?s ?name ?tsid WHERE {
  ?s rdfs:label ?name .
  ?s ref:hasExternalReference [ ref:hasTimeseriesId ?tsid ] .
  FILTER(CONTAINS(?name, "CoolingTower"))
}

SELECT ?s ?name ?pred WHERE {
  ?s rdfs:label ?name .
  ?s ?pred ?o .
  FILTER(CONTAINS(?name, "Chiller") || CONTAINS(?name, "CondPump") || CONTAINS(?name, "CoolingTower"))
}

SELECT ?point ?name ?tsid WHERE {
  ?point rdfs:label ?name .
  ?point brick:isPointOf? ?none .
  ?point ref:hasExternalReference [ ref:hasTimeseriesId ?tsid ] .
  FILTER (CONTAINS(?name, "Pump") || CONTAINS(?name, "Chiller") || CONTAINS(?name, "Tower"))
}

